CREATE TABLE ai_usage (id TEXT PRIMARY KEY, family_id TEXT NOT NULL, member_id TEXT NOT NULL, operation TEXT NOT NULL, request_key TEXT NOT NULL, request_hash TEXT NOT NULL, state TEXT NOT NULL, day TEXT NOT NULL, started_epoch INTEGER NOT NULL, input_tokens INTEGER, output_tokens INTEGER, duration_ms INTEGER, output_content TEXT, UNIQUE(member_id,request_key));
CREATE INDEX ai_usage_family_day ON ai_usage(family_id,day);
CREATE TABLE proposals (id TEXT PRIMARY KEY, family_id TEXT NOT NULL, member_id TEXT NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, source_text TEXT NOT NULL, profile_version INTEGER NOT NULL, base_versions TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'draft', expires INTEGER NOT NULL, usage_id TEXT UNIQUE, result TEXT, created_at TEXT NOT NULL);
CREATE TABLE menu_ingredients (menu_id TEXT NOT NULL REFERENCES menus(id), position INTEGER NOT NULL, name TEXT NOT NULL, quantity TEXT, unit TEXT NOT NULL, PRIMARY KEY(menu_id,position));
